    "site.workflowAnalytics.fullCatalog.0":
      "显式资源份额、容量与执行区间；父子用量去重并保留币种。",
    "site.workflowAnalytics.fullCatalog.1":
      "历史燃尽、燃起、速度、累积流、周期时间与条件化预测模型。",
    "site.workflowAnalytics.fullCatalog.2":
      "按指标版本校验维度、分段、单位与图型，固定调用方权限范围。",
    "site.workflowAnalytics.fullCatalog.3":
      "可保留的布局草稿与带操作编号、版本的保存回执；unknown 先核对。",
    "site.workflowAnalytics.fullCatalog.4":
      "由调用方触发，导出当前授权聚合 SVG 及口径和模拟标记。",
    "site.workflowAnalytics.fullCatalog.5":
      "资源热图与 HeatmapLegend；已知、未知、零容量与超载分离。",
    "site.workflowAnalytics.fullCatalog.6":
      "人员日期单元到显式分配清单与排期回调。",
    "site.workflowAnalytics.fullCatalog.7":
      "实际时间戳区间与可访问数据表，运行和验收状态分离。",
    "site.workflowAnalytics.fullCatalog.8":
      "Burndown/Burnup/Velocity/CFD/CycleTime/StateResidence/Workload/AgentCost 模板，保留专业口径。",
